//! QA-01.3 minimal chart / pivot / page fixtures.
//!
//! These fixtures are generated by `scripts/qa01_extended_samples.py` and are
//! intentionally separate from the formula sample.  The test only claims that
//! load / save / re-load preserves the object and that the pivot result is
//! computed from the synthetic table; it is not a substitute for the
//! three-party Office matrix.

use sheetcore::pivot::{Agg, PivotSpec};
use std::path::{Path, PathBuf};

fn fixture(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/qa01_extended")
        .join(name)
}

fn out(name: &str) -> PathBuf {
    std::env::current_exe()
        .expect("test executable path")
        .parent()
        .expect("test executable directory")
        .join(format!("{name}_{}.xlsx", std::process::id()))
}

#[test]
fn chart_object_survives_load_save_reload() {
    let src = fixture("chart.xlsx");
    assert!(src.exists(), "required fixture missing: {}", src.display());
    let wb = sheetcore::xlsx::load(&src).expect("load chart fixture");
    let sh = wb.sheet(0);
    assert_eq!(sh.charts.len(), 1, "fixture should contain one chart: {:?}", sh.charts);
    let title = sh.charts[0].title.clone();

    let dst = out("qa01_chart");
    let _ = std::fs::remove_file(&dst);
    sheetcore::xlsx::save(&dst, &wb).expect("save chart fixture");
    let back = sheetcore::xlsx::load(&dst).expect("reload chart output");
    assert_eq!(back.sheet(0).charts.len(), 1);
    assert_eq!(back.sheet(0).charts[0].title, title);
    let _ = std::fs::remove_file(&dst);
}

#[test]
fn pivot_computes_and_writes_from_extended_table() {
    let src = fixture("table.xlsx");
    assert!(src.exists(), "required fixture missing: {}", src.display());
    let mut wb = sheetcore::xlsx::load(&src).expect("load table fixture");
    let region = sheetcore::sort_filter::current_region(wb.sheet(0), 1, 1);
    assert_eq!(region, (0, 0, 5, 2));
    let spec = PivotSpec {
        source: region,
        row_field: 1,
        col_field: None,
        value_field: 2,
        agg: Agg::Sum,
        group: sheetcore::pivot::GroupBy::None,
        exclude: Vec::new(),
    };
    let result = sheetcore::pivot::compute(wb.sheet(0), &spec);
    assert_eq!(result.headers, vec!["部门", "金额"]);
    let get = |name: &str| -> Option<f64> {
        result.rows.iter().find(|r| r[0].display() == name).and_then(|r| {
            match r[1] {
                sheetcore::model::Value::Number(n) => Some(n),
                _ => None,
            }
        })
    };
    assert_eq!(get("研发"), Some(500.0));
    assert_eq!(get("销售"), Some(500.0));
    assert_eq!(get("行政"), Some(50.0));
    let rect = sheetcore::pivot::write_to(wb.sheet_mut(0), (0, 6), &result);
    assert_eq!(rect.1, 6);
    wb.dirty = true;

    let dst = out("qa01_pivot");
    let _ = std::fs::remove_file(&dst);
    sheetcore::xlsx::save(&dst, &wb).expect("save pivot output");
    let back = sheetcore::xlsx::load(&dst).expect("reload pivot output");
    assert_eq!(back.sheet(0).get(0, 6).unwrap().value.display(), "部门");
    assert_eq!(back.sheet(0).get(1, 6).unwrap().value.display(), "研发");
    assert_eq!(back.sheet(0).get(1, 7).unwrap().value.display(), "500");
    let _ = std::fs::remove_file(&dst);
}

#[test]
fn page_settings_survive_load_and_save() {
    let src = fixture("page.xlsx");
    assert!(src.exists(), "required fixture missing: {}", src.display());
    let wb = sheetcore::xlsx::load(&src).expect("load page fixture");
    let page = &wb.sheet(0).page;
    assert!(page.landscape);
    assert_eq!(page.paper, 8);
    assert_eq!(page.scale, 85);
    assert!((page.margins[0] - 0.5).abs() < 1e-6);
    assert!(page.gridlines);
    assert_eq!(page.print_area, Some((0, 0, 39, 7)));
    assert_eq!(page.title_rows, Some((0, 1)));

    let dst = out("qa01_page");
    let _ = std::fs::remove_file(&dst);
    sheetcore::xlsx::save(&dst, &wb).expect("save page fixture");
    let back = sheetcore::xlsx::load(&dst).expect("reload page output");
    let back_page = &back.sheet(0).page;
    assert!(back_page.landscape);
    assert_eq!(back_page.paper, 8);
    assert_eq!(back_page.scale, 85);
    assert_eq!(back_page.print_area, Some((0, 0, 39, 7)));
    assert_eq!(back_page.title_rows, Some((0, 1)));
    let _ = std::fs::remove_file(&dst);
}
